public async Task<ProductPage> GetPageAsync(int id, CancellationToken ct)
{
    var product = await _catalog.GetAsync(id, ct);                  // critical: let failures surface

    IReadOnlyList<ProductSummary> recs = [];
    var recsAvailable = true;
    try
    {
        recs = await _recommendations.GetForAsync(id, ct);           // short timeouts + breaker on this client
    }
    catch (Exception ex) when (ex is HttpRequestException or TimeoutRejectedException or BrokenCircuitException)
    {
        recsAvailable = false;                                       // degrade: page without the section
        _log.LogWarning(ex, "Recommendations unavailable for product {ProductId}", id);
    }

    return new ProductPage(product, recs, recsAvailable);
}

