public sealed class OrderService(AppDbContext db)
{
    private static readonly ActivitySource Source = new("Shop.Orders");

    public async Task<int> PlaceAsync(PlaceOrder cmd, CancellationToken ct)
    {
        using var activity = Source.StartActivity("PlaceOrder");   // child of the incoming request span
        activity?.SetTag("order.lines", cmd.Lines.Count);

        var order = Order.From(cmd);
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct);
        return order.Id;
    }
}

