public static IQueryable<Order> ApplySort(this IQueryable<Order> q, string? sort, bool desc) =>
    (sort?.ToLowerInvariant(), desc) switch
    {
        ("total", false)   => q.OrderBy(o => o.Total).ThenBy(o => o.Id),
        ("total", true)    => q.OrderByDescending(o => o.Total).ThenBy(o => o.Id),
        ("created", true)  => q.OrderByDescending(o => o.CreatedUtc).ThenBy(o => o.Id),
        _                  => q.OrderBy(o => o.CreatedUtc).ThenBy(o => o.Id)   // default and unknown values
    };

