app.MapGet("/reports/status/{jobId:guid}", async (Guid jobId, IReportJobs jobs, HttpResponse response, CancellationToken ct) =>
{
    var job = await jobs.FindAsync(jobId, ct);
    if (job is null) return Results.NotFound();

    if (job.Status == JobStatus.Succeeded)
    {
        response.Headers.Location = $"/reports/{job.ReportId}";
        return Results.StatusCode(StatusCodes.Status303SeeOther);      // go to the result
    }

    response.Headers.RetryAfter = "10";                               // poll again in ~10 s
    return Results.Ok(new { job.Status, job.Progress });
});

