builder.Services.AddHttpClient("webhooks")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler
    {
        AllowAutoRedirect = false,                  // a redirect could point inside the network
        ConnectCallback = async (ctx, ct) =>
        {
            var addresses = await Dns.GetHostAddressesAsync(ctx.DnsEndPoint.Host, ct);
            var ip = addresses.First();
            if (IPAddress.IsLoopback(ip) || IsPrivateOrLinkLocal(ip))   // your helper: RFC 1918, fc00::/7, 169.254/16, fe80::/10
                throw new HttpRequestException("Destination not allowed");

            var socket = new Socket(SocketType.Stream, ProtocolType.Tcp) { NoDelay = true };
            await socket.ConnectAsync(ip, ctx.DnsEndPoint.Port, ct);   // connect to the IP we checked
            return new NetworkStream(socket, ownsSocket: true);
        }
    });

