public sealed class OutboxRelay(ILogger<OutboxRelay> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await PublishPendingAsync(stoppingToken);                   // pass the token down
            await Task.Delay(TimeSpan.FromSeconds(2), stoppingToken);
        }
        log.LogInformation("Outbox relay stopped cleanly");
    }

    private Task PublishPendingAsync(CancellationToken ct) => Task.CompletedTask; // real work here
}

